create table public.clients (                                id bigint generated by default as identity not null,                                created_at timestamp with time zone not null default now(),                                user_telegram_id character varying null,                                first_name character varying null,                                last_name character varying null,                                last_message_at timestamp without time zone not null,                                constraint clients_pkey primary key (id)) TABLESPACE pg_default;create table public.messages (                                 id bigint generated by default as identity not null,                                 created_at timestamp with time zone not null default now(),                                 author character varying null,                                 body text null,                                 messanger_user_id character varying null,                                 messenger_type character varying null,                                 client_id bigint not null,                                 constraint messages_pkey primary key (id),                                 constraint messages_client_id_fkey foreign KEY (client_id) references clients (id)) TABLESPACE pg_default;